                # Extract product
                prod_match = re.search(r"(\w+)\s+runs out of stock", line)
                if prod_match:
                    kind = "run_out_of_stock"
                    entities.append(prod_match.group(1))
            elif "fully backordered" in line:
                kind = "order_fully_backordered"
                prod_match = re.search(r"(\w+)", line)
                if prod_match:
                    entities.append(prod_match.group(1))
            elif "backlog cleared" in line:
                kind = "backlog_cleared"
                prod_match = re.search(r"(\w+)", line)
                if prod_match:
                    entities.append(prod_match.group(1))

            if kind is not None and day is not None:
                outcomes_list.append(
                    {
                        "time": day,
                        "kind": kind,
                        "entities": entities,
                        "value": None,
                        "src": [[events_node["node_id"], line_idx]],
                    }
                )
    return outcomes_list


