                    "fields": {"opening_stock": stk},
                    "src": [[prod_node["node_id"], row_idx, ["opening stock"]]],
                })

    # 3.2 Daily production & orders
    ledger = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger and ledger.get("kind") == "table":
        for row_idx, row in table_rows(ledger):
            day = _int(row.get("day"))
            prod = row.get("product")
            if day is None or not prod:
                continue
            produced = _int(row.get("produced"))
            if produced is not None:
                inp.append({
                    "id": f"produced_{prod}_day_{day}",
                    "time": float(day),
                    "kind": "production",
                    "entities": [prod],
                    "fields": {"produced": produced},
                    "src": [[ledger["node_id"], row_idx, ["produced"]]],
                })
            ordered = _int(row.get("ordered"))
            if ordered is not None:
                inp.append({
                    "id": f"order_{prod}_day_{day}",
                    "time": float(day),
                    "kind": "order",
                    "entities": [prod],
                    "fields": {"ordered": ordered},
                    "src": [[ledger["node_id"], row_idx, ["ordered"]]],
                })

    # 3.3 Future order book (planned production & orders)
    ob_node = node_by_title(doc, f"{scope}: Order book: Orders received and production planned for days 15 to 21")
    if ob_node and ob_node.get("kind") == "table":
        for row_idx, row in table_rows(ob_node):
            day = _int(row.get("day"))
            prod = row.get("product")
            if day is None or not prod:
                continue
            planned = _int(row.get("planned production"))
            if planned is not None:
                inp.append({
                    "id": f"planned_prod_{prod}_day_{day}",
                    "time": float(day),
                    "kind": "planned_production",
                    "entities": [prod],
                    "fields": {"planned_production": planned},
                    "src": [[ob_node["node_id"], row_idx, ["planned production"]]],
                })
            ordered = _int(row.get("ordered"))
            if ordered is not None:
                inp.append({
                    "id": f"planned_order_{prod}_day_{day}",
                    "time": float(day),
                    "kind": "planned_order",
                    "entities": [prod],
                    "fields": {"ordered": ordered},
                    "src": [[ob_node["node_id"], row_idx, ["ordered"]]],
                })

    return inp

# --------------------------------------------------------------------
# 4. outcomes
# --------------------------------------------------------------------
def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Recorded results produced by the process: ledger figures and event list."""
    out: List[Dict[str, Any]] = []

    # 4.1 Ledger outputs (shipped, backordered, stock)
    ledger = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger and ledger.get("kind") == "table":
        for row_idx, row in table_rows(ledger):
            day = _int(row.get("day"))
            prod = row.get("product")
            if day is None or not prod:
                continue
            for kind in ("shipped", "backordered", "stock"):
                val = _int(row.get(kind))
                if val is not None:
                    out.append({
                        "time": float(day),
                        "kind": kind,
                        "entities": [prod],
                        "value": val,
                        "src": [[ledger["node_id"], row_idx, [kind]]],
                    })

    # 4.2 Event list
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node and ev_node.get("kind") == "list":
        plant_entities = [e["id"] for e in entities(doc, scope)]
        for ln_idx, line in enumerate(ev_node.get("lines", [])):
            m_day = re.search(r"Day\s+(\d+)", line)
            if not m_day:
                continue
            day = int(m_day.group(1))
            ev_kind = None
            ev_ents: List[str] = []

            if "dispatch capacity reached" in line:
                ev_kind = "capacity_reached"
                ev_ents = []
            elif "runs out of stock" in line:
                ev_kind = "run_out_of_stock"
                pid = None
                for p in plant_entities:
                    if re.search(rf"\b{re.escape(p)}\b", line):
                        pid = p
                        break
                if pid:
                    ev_ents = [pid]
            elif "fully backordered" in line:
                ev_kind = "order_fully_backordered"
                pid = None
                for p in plant_entities:
                    if re.search(rf"\b{re.escape(p)}\b", line):
                        pid = p
                        break
                if pid:
                    ev_ents = [pid]
            elif "backlog cleared" in line or "backlog of" in line:
                ev_kind = "backlog_cleared"
                pid = None
                for p in plant_entities:
                    if re.search(rf"\b{re.escape(p)}\b", line):
                        pid = p
                        break
                if pid:
                    ev_ents = [pid]
            else:
                continue  # ignore non-event lines

            out.append({
                "time": float(day),
                "kind": ev_kind,
                "entities": ev_ents,
                "value": None,
                "src": [[ev_node["node_id"], ln_idx]],
            })

    return out

# --------------------------------------------------------------------
# 5. params
# --------------------------------------------------------------------
def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return dictionary of numeric constants for the scope."""
    params: Dict[str, Any] = {}

    plant_node = node_by_title(doc, scope)
    if plant_node and plant_node.get("kind") == "text":
        text = plant_node.get("text", "")
        m = re.search(r"Daily dispatch capacity:\s*([\d,\.]+)\s*kg", text)
        if m:
            val = float(m.group(1).replace(",", ""))
            params["dispatch_capacity"] = val
    return params
